	ops = append(ops, diffStringField(base, []string{"dhcp-options", "user-class"}, prev.DHCPOptionsUserClass, cur.DHCPOptionsUserClass)...)

	ops = append(ops, diffBoolField(base, []string{"dhcp-options", "no-default-route"}, prev.DHCPOptionsNoDefaultRoute, cur.DHCPOptionsNoDefaultRoute)...)

	ops = append(ops, diffIntField(base, []string{"dhcp-options", "default-route-distance"}, prev.DHCPOptionsDefaultRouteDistance, cur.DHCPOptionsDefaultRouteDistance)...)

	ops = append(ops, diffMultiField(base, []string{"dhcp-options", "reject"}, prev.DHCPOptionsReject, cur.DHCPOptionsReject)...)

	ops = append(ops, diffStringField(base, []string{"dhcpv6-options", "duid"}, prev.Dhcpv6OptionsDuid, cur.Dhcpv6OptionsDuid)...)

	ops = append(ops, diffBoolField(base, []string{"dhcpv6-options", "parameters-only"}, prev.Dhcpv6OptionsParametersOnly, cur.Dhcpv6OptionsParametersOnly)...)

	ops = append(ops, diffBoolField(base, []string{"dhcpv6-options", "no-request-domain-name"}, prev.Dhcpv6OptionsNoRequestDomainName, cur.Dhcpv6OptionsNoRequestDomainName)...)

	ops = append(ops, diffBoolField(base, []string{"dhcpv6-options", "no-request-dns"}, prev.Dhcpv6OptionsNoRequestDNS, cur.Dhcpv6OptionsNoRequestDNS)...)

	ops = append(ops, diffBoolField(base, []string{"dhcpv6-options", "rapid-commit"}, prev.Dhcpv6OptionsRapidCommit, cur.Dhcpv6OptionsRapidCommit)...)

	ops = append(ops, diffBoolField(base, []string{"dhcpv6-options", "temporary"}, prev.Dhcpv6OptionsTemporary, cur.Dhcpv6OptionsTemporary)...)

	ops = append(ops, diffBoolField(base, []string{"dhcpv6-options", "no-release"}, prev.Dhcpv6OptionsNoRelease, cur.Dhcpv6OptionsNoRelease)...)

	ops = append(ops, diffStringField(base, []string{"ip", "adjust-mss"}, prev.IPAdjustMss, cur.IPAdjustMss)...)

	ops = append(ops, diffIntField(base, []string{"ip", "arp-cache-timeout"}, prev.IPARPCacheTimeout, cur.IPARPCacheTimeout)...)

	ops = append(ops, diffBoolField(base, []string{"ip", "disable-arp-filter"}, prev.IPDisableARPFilter, cur.IPDisableARPFilter)...)

	ops = append(ops, diffBoolField(base, []string{"ip", "disable-forwarding"}, prev.IPDisableForwarding, cur.IPDisableForwarding)...)

	ops = append(ops, diffBoolField(base, []string{"ip", "enable-directed-broadcast"}, prev.IPEnableDirectedBroadcast, cur.IPEnableDirectedBroadcast)...)

	ops = append(ops, diffBoolField(base, []string{"ip", "enable-arp-accept"}, prev.IPEnableARPAccept, cur.IPEnableARPAccept)...)

